def handler(context):
    # The prompt researches by domain, so there is nothing to classify against.
    # Emitted rather than dropped so the export can account for every input row.
    def s(key):
        v = context.get_input(key)
        return "" if v is None else str(v).strip()

    return {"company_name": s("company_name"), "domain": "",
            "Side": "", "Classification": "", "skipped_reason": "no domain"}
